import type { AppliedOperation, OperationId } from '../operations/registry';

// The studio's cleaning steps as pandas code, step by step, so the report's
// "how the data was prepared" can be re-run exactly. Generated by rules from the
// recorded operations (no AI).

/** A Python string literal. */
export const py = (s: unknown) => `'${String(s).replace(/\\/g, '\\\\').replace(/'/g, "\\'").replace(/\n/g, '\\n')}'`;
const pyVal = (v: unknown): string => (v === null || v === undefined ? 'None' : typeof v === 'number' ? String(v) : typeof v === 'boolean' ? (v ? 'True' : 'False') : py(v));
const col = (c: string) => `df[${py(c)}]`;

const FILTER: Record<string, (c: string, v: unknown) => string> = {
  equals: (c, v) => `${col(c)} == ${pyVal(v)}`,
  not_equals: (c, v) => `${col(c)} != ${pyVal(v)}`,
  greater_than: (c, v) => `pd.to_numeric(${col(c)}, errors="coerce") > ${pyVal(Number(v))}`,
  less_than: (c, v) => `pd.to_numeric(${col(c)}, errors="coerce") < ${pyVal(Number(v))}`,
  contains: (c, v) => `${col(c)}.astype(str).str.contains(${pyVal(v)}, case=False, regex=False, na=False)`,
  is_empty: c => `${col(c)}.isna() | (${col(c)}.astype(str).str.strip() == "")`,
  is_not_empty: c => `~(${col(c)}.isna() | (${col(c)}.astype(str).str.strip() == ""))`,
};
const AGG: Record<string, string> = { count: 'count', count_distinct: 'nunique', sum: 'sum', mean: 'mean', median: 'median', min: 'min', max: 'max' };
const TYPES: Record<string, string> = {
  numeric: 'pd.to_numeric({c}, errors="coerce")', categorical: '{c}.astype("string")', boolean: '{c}.map(lambda v: str(v).strip().lower() in ("true", "yes", "1", "y"))', datetime: 'pd.to_datetime({c}, errors="coerce")',
};

/** One step as pandas, with a comment saying what it does. */
export function stepCode(step: AppliedOperation): string {
  const p = step.params as any;
  switch (step.op as OperationId) {
    case 'drop_columns': return `df = df.drop(columns=[${p.columns.map(py).join(', ')}])`;
    case 'rename_column': return `df = df.rename(columns={${py(p.from)}: ${py(p.to)}})`;
    case 'fill_missing': {
      const fill = p.strategy === 'mean' ? `${col(p.column)}.mean()` : p.strategy === 'median' ? `${col(p.column)}.median()` : p.strategy === 'mode' ? `${col(p.column)}.mode().iloc[0]` : p.strategy === 'zero' ? '0' : pyVal(p.value);
      return `${col(p.column)} = ${col(p.column)}.fillna(${fill})`;
    }
    case 'add_column': return `${col(p.name)} = ${pyVal(p.value)}`;
    case 'add_row': return `df = pd.concat([df, pd.DataFrame([${'{'}${Object.entries(p.values ?? {}).map(([k, v]) => `${py(k)}: ${pyVal(v)}`).join(', ')}${'}'}])], ignore_index=True)`;
    case 'delete_rows': return `df = df.drop(index=[${(p.indices ?? []).join(', ')}]).reset_index(drop=True)`;
    case 'filter_rows': return `df = df[${(FILTER[p.operator] ?? FILTER.equals)(p.column, p.value)}].reset_index(drop=True)`;
    case 'remove_duplicates': return 'df = df.drop_duplicates().reset_index(drop=True)';
    case 'derive_column': {
      const name = p.name || `${p.source}_${p.transform}`;
      const s = `pd.to_numeric(${col(p.source)}, errors="coerce")`;
      const o = p.other ? `pd.to_numeric(${col(p.other)}, errors="coerce")` : '1';
      const expr = { log: `np.log1p(${s})`, sqrt: `np.sqrt(${s})`, square: `${s} ** 2`, minmax: `(${s} - ${s}.min()) / (${s}.max() - ${s}.min())`, standard: `(${s} - ${s}.mean()) / ${s}.std()`, multiply: `${s} * ${o}`, divide: `${s} / ${o}.replace(0, np.nan)` }[p.transform as string] ?? s;
      return `${col(name)} = ${expr}`;
    }
    case 'one_hot_encode': return `df = pd.get_dummies(df, columns=[${py(p.column)}], prefix=${py(p.prefix || p.column)}, dtype=int)`;
    case 'standardize_text': {
      let e = `${col(p.column)}.astype("string")`;
      if (p.trim !== false) e += '.str.strip()';
      if (p.collapseSpaces !== false) e += '.str.replace(r"\\s+", " ", regex=True)';
      if (p.case && p.case !== 'none') e += `.str.${p.case}()`;
      return `${col(p.column)} = ${e}`;
    }
    case 'replace_values': return p.matchCase === false
      ? `${col(p.column)} = ${col(p.column)}.mask(${col(p.column)}.astype(str).str.lower() == ${py(String(p.from).toLowerCase())}, ${pyVal(p.to)})`
      : `${col(p.column)} = ${col(p.column)}.replace(${pyVal(p.from)}, ${pyVal(p.to)})`;
    case 'convert_type': return `${col(p.column)} = ${(TYPES[p.to] ?? TYPES.categorical).replace(/\{c\}/g, col(p.column))}`;
    case 'join': return `right = pd.read_csv(${py(`${p.right?.name ?? 'right'}.csv`)})  # the table that was joined\ndf = df.merge(right, left_on=${py(p.leftKey)}, right_on=${py(p.rightKey)}, how=${py(p.how)})`;
    case 'append_rows': return `extra = pd.read_csv(${py(`${p.right?.name ?? 'extra'}.csv`)})  # the rows that were appended\ndf = pd.concat([df, extra], ignore_index=True)`;
    case 'group_aggregate': return `df = df.groupby([${p.by.map(py).join(', ')}], dropna=False).agg(**{${p.aggregations.map((a: any) => `${py(`${a.column}_${a.fn}`)}: (${py(a.column)}, ${py(AGG[a.fn] ?? a.fn)})`).join(', ')}}).reset_index()`;
    case 'pivot': return `df = df.pivot_table(index=${py(p.index)}, columns=${py(p.columns)}, values=${py(p.values)}, aggfunc=${py(AGG[p.fn] ?? p.fn)}).reset_index()`;
    default: return `# (${String(step.op)}: not expressible in pandas here)`;
  }
}

/** A whole, runnable preparation script: load the original file, apply each step in order, save. */
export function pandasScript(opts: { sourceFile: string; steps: { label: string; op: AppliedOperation }[]; skipped?: string[] }): string {
  const lines = [
    '# Data preparation, as done in Data Science Studio',
    `# Re-runs each recorded step on the original file. Generated ${new Date().toISOString().slice(0, 10)}.`,
    'import numpy as np',
    'import pandas as pd',
    '',
    `df = pd.read_csv(${py(opts.sourceFile)})`,
    'print("original:", df.shape)',
    '',
  ];
  opts.steps.forEach((s, i) => { lines.push(`# ${i + 1}. ${s.label}`, stepCode(s.op), ''); });
  for (const s of opts.skipped ?? []) lines.push(`# Not reproducible as code: ${s}`);
  lines.push('print("prepared:", df.shape)', 'df.to_csv("prepared.csv", index=False)');
  return lines.join('\n');
}
